import { useEffect, useRef, useState, useSyncExternalStore, type FormEvent, type ReactNode } from 'react';
import { Button, TextField, TextareaField, Dialog, DialogContent, DialogTitle, DialogDescription, useNimiTheme } from '@nimiplatform/kit/ui';
import { ArrowUpRight, ArrowRight, Plus, Search, ChevronLeft, ChevronRight, Play, Square, FileText, Folder, Layers, Sparkles, Clock3, Settings2, Check, AlertCircle, X, RefreshCw, Link2, Upload, Pencil, BookOpen, MoreHorizontal, Mic, Volume2, Sun, Moon, Archive, Copy, ExternalLink, Bot } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { invokeAvatarHostHandoffMechanic } from '@nimiplatform/kit/shell/renderer/bridge';
import { invokeAvatarHostHandoff, type AvatarHostHandoffTarget } from '@nimiplatform/kit/features/avatar/headless';
import { AgentRealtimeEntry, createBrowserAgentRealtimeHostMediaPort } from '@nimiplatform/kit/features/agent-realtime';
import { engine } from './host-client';
import { attentionWorks, nextWorkAction, skillPresentation, visibleActivities } from './workbench-view';
import type { NimiAppActivityRecord } from '@nimiplatform/sdk';
import { statusLabel, nextRoutineTime, now, uuid, workCanEdit, errorText, deliverableReadReference, type Work, type Skill, type Routine, type Material, type Deliverable } from './model';
import '@nimiplatform/kit/ui/themes/dark.css';
import './go.css';

type View = 'work' | 'deliverables' | 'skills' | 'routines' | 'sources';
type Modal = 'work' | 'projects' | 'project' | 'agent' | 'material' | 'skill' | 'routine' | 'voice' | 'settings' | 'avatar-switch' | null;
const nav: { id: View; name: string; icon: ReactNode }[] = [
  { id: 'work', name: '工作台', icon: <Layers size={18}/> }, { id: 'deliverables', name: '成果库', icon: <FileText size={18}/> },
  { id: 'skills', name: '工作方法', icon: <Sparkles size={18}/> }, { id: 'routines', name: '例行工作', icon: <Clock3 size={18}/> }, { id: 'sources', name: '生态来源', icon: <Link2 size={18}/> },
];
const date = (value: string) => new Date(value).toLocaleString('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
const active = (work: Work) => ['running', 'needs-input', 'queued'].includes(work.status);
function Status({ work }: { work: Work }) { return <span className={`go-status ${work.status}`}><i/>{statusLabel[work.status]}</span>; }
function Markdown({ content }: { content: string }) { return <div className="go-markdown"><ReactMarkdown remarkPlugins={[remarkGfm]} components={{ a: ({ children }) => <span className="go-source-link">{children}</span> }}>{content}</ReactMarkdown></div>; }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="go-empty"><div className="go-empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <div className="go-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</div>; }

export function GoApp() {
  useSyncExternalStore(engine.subscribe, engine.snapshot);
  const theme = useNimiTheme();
  const [view, setView] = useState<View>('work');
  const [projectId, setProjectId] = useState<string>('all');
  const [workId, setWorkId] = useState<string | null>(null);
  const [workDraft, setWorkDraft] = useState<{ workId: string; text: string } | null>(null);
  const [search, setSearch] = useState('');
  const [modal, setModal] = useState<Modal>(null);
  const [skill, setSkill] = useState<Skill | null>(null);
  const [routine, setRoutine] = useState<Routine | null>(null);
  const [editingProject, setEditingProject] = useState<NonNullable<typeof engine.workspace>['projects'][number] | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<{ workId: string; id: string } | null>(null);
  const [archive, setArchive] = useState(false);
  const [attentionOnly, setAttentionOnly] = useState(false);
  const [busy, setBusy] = useState(false);
  const [avatarNotice, setAvatarNotice] = useState('');
  const [avatarBusy, setAvatarBusy] = useState(false);
  const [avatarSwitch, setAvatarSwitch] = useState<{ target: AvatarHostHandoffTarget; name: string } | null>(null);
  const closeModal = () => { if (modal === 'avatar-switch') { setAvatarSwitch(null); setAvatarNotice('已取消切换'); } setModal(null); };
  const confirmAvatarSwitch = async () => {
    if (!avatarSwitch) return;
    setAvatarBusy(true);
    try {
      const result = await invokeAvatarHostHandoff({ invoke: invokeAvatarHostHandoffMechanic }, { command: 'launch', target: avatarSwitch.target });
      if (result.state !== 'present' && result.state !== 'focused') throw new Error('桌面伙伴的状态已变化，请重新发起切换。');
      setAvatarNotice(`${avatarSwitch.name}的形象已在桌面就绪，工作和成果仍保留在这里。`);
    } catch (error) { setAvatarNotice(''); engine.report(error); }
    finally { setAvatarBusy(false); setAvatarSwitch(null); setModal(null); }
  };
  const perform = async (action: () => Promise<unknown>, close = false) => { setBusy(true); engine.clearError(); try { await action(); if (close) setModal(null); } catch (error) { engine.report(error); } finally { setBusy(false); } };
  useEffect(() => { document.documentElement.lang = 'zh-CN'; void engine.initialize(); return () => engine.disconnect(); }, [engine]);
  useEffect(() => { if (engine.selectedWork) { setView('work'); setWorkId(engine.selectedWork); engine.selectedWork = null; } }, [engine.snapshot()]);
  useEffect(() => { theme.setScheme(engine.workspace?.theme || 'light'); document.documentElement.style.colorScheme = engine.workspace?.theme || 'light'; }, [engine.workspace?.theme]);
  useEffect(() => { if (workId && engine.ready) void engine.hydrate(workId).catch(error => engine.report(error)); }, [workId, engine, engine.ready]);
  useEffect(() => { const key = (event: KeyboardEvent) => { if (engine.ready && (event.metaKey || event.ctrlKey) && event.key === 'n') { event.preventDefault(); setModal('work'); } }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, [selectedDoc]);
  const workspace = engine.workspace;
  const projects = workspace?.projects.filter(p => !p.archived) || [];
  const currentWork = engine.works.find(w => w.id === workId);
  const visible = engine.works.filter(w => w.archived === archive && (projectId === 'all' || w.projectId === projectId) && (!attentionOnly || attentionWorks([w]).length > 0) && (!search || `${w.title} ${w.brief}`.toLowerCase().includes(search.toLowerCase()))).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  const selectedProject = projects.find(p => p.id === projectId);
  const selectedTitle = nav.find(n => n.id === view)!.name;
  const projectWorks = engine.works.filter(w => !w.archived && (projectId === 'all' || w.projectId === projectId));
  const attention = attentionWorks(projectWorks);
  const recentDocs = projectWorks.flatMap(work => work.deliverables.map(doc => ({ work, doc }))).sort((a, b) => b.doc.revisions.at(-1)!.createdAt.localeCompare(a.doc.revisions.at(-1)!.createdAt)).slice(0, 3);
  const docs = engine.works.filter(w => !w.archived && (projectId === 'all' || w.projectId === projectId)).flatMap(w => w.deliverables.map(d => ({ work: w, doc: d }))).filter(({ doc }) => !search || doc.title.toLowerCase().includes(search.toLowerCase()));
  const openDoc = (id: string, docId: string) => setSelectedDoc({ workId: id, id: docId });
  const avatar = async () => {
    setAvatarBusy(true); engine.clearError(); setAvatarNotice('正在连接桌面上的搭档…');
    try {
    const agent = engine.agent; if (!agent) { setModal('agent'); return; }
    const conversation = await engine.client.conversation.open({ agentHandle: agent.agentHandle });
    const target = { agentHandle: agent.agentHandle, conversationAnchorId: conversation.conversationAnchorId, avatarInstanceId: null, launchSource: 'nimi.go', switchIntentRef: null, committedPresentationRef: null, temporaryCustodyRef: null };
    const result = await invokeAvatarHostHandoff({ invoke: invokeAvatarHostHandoffMechanic }, { command: 'launch', target });
    if (result.state === 'confirmation-required') {
      setAvatarSwitch({ name: agent.displayName, target: { ...target, switchIntentRef: result.switchIntentRef } });
      setAvatarNotice('等待你确认桌面伙伴的切换。'); setModal('avatar-switch'); return;
    }
    if (result.state !== 'present' && result.state !== 'focused') throw new Error('形象尚未就绪，请稍后重试或在 Nimi 检查搭档的形象设置。');
    setAvatarNotice(`${agent.displayName}的形象已在桌面就绪，工作和成果仍保留在这里。`);
    } catch (error) { setAvatarNotice(''); engine.report(error); } finally { setAvatarBusy(false); }
  };
  return <div className="go-app">
    <aside className="go-sidebar">
      <button className="go-brand" onClick={() => { setView('work'); setWorkId(null); setProjectId('all'); }} aria-label="NimiGo 首页"><span className="go-mark"><ArrowUpRight size={25} strokeWidth={2.5}/></span><span>Nimi<span className="go-brand-go">Go</span></span><small>WORKSPACE</small></button>
      <Button className="go-new-work" tone="primary" leadingIcon={<Plus size={17}/>} onClick={() => setModal('work')} disabled={!engine.ready}>新建工作 <kbd>⌘ N</kbd></Button>
      <nav aria-label="主导航">{nav.map(item => <button key={item.id} aria-label={item.name} title={item.name} className={`go-nav-item ${view === item.id ? 'selected' : ''}`} onClick={() => { setView(item.id); setWorkId(null); setSearch('');  }}>{item.icon}<span>{item.name}</span>{item.id === 'work' && engine.active && <i className="go-live-dot"/>}</button>)}</nav>
      <button className="go-compact-projects go-nav-item" aria-label="选择项目" title="选择项目" disabled={!engine.ready} onClick={() => setModal('projects')}><Folder size={18}/></button>
      <div className="go-section-label">项目<button aria-label="新建项目" disabled={!engine.ready} onClick={() => { setEditingProject(null); setModal('project'); }}><Plus size={15}/></button></div>
      <div className="go-projects"><button className={projectId === 'all' ? 'selected' : ''} onClick={() => { setProjectId('all'); setWorkId(null); setView('work'); }}><Folder size={15}/><span>全部项目</span><small>{engine.works.filter(w => !w.archived).length}</small></button>{projects.map((p, index) => <button key={p.id} className={projectId === p.id ? 'selected' : ''} onClick={() => { setProjectId(p.id); setWorkId(null); setView('work'); }}><i style={{ background: ['#7465c7', '#1e958c', '#c49240', '#b56579'][index % 4] }}/><span>{p.name}</span></button>)}</div>
      <div className="go-sidebar-bottom"><div className="go-agent-label"><span>你的工作搭档</span><button aria-label="刷新 Agent" onClick={() => void engine.refreshAgents()}><RefreshCw size={13}/></button></div><button className="go-agent-card" aria-label={engine.agent ? `工作搭档：${engine.agent.displayName}` : '选择工作搭档'} title="工作搭档" disabled={!engine.ready} onClick={() => setModal('agent')}><span className="go-agent-avatar">{engine.agent?.avatarUrl ? <img src={engine.agent.avatarUrl} alt=""/> : <Bot size={22}/>}</span><span><strong>{engine.agent?.displayName || '选择你的 Agent'}</strong><small>{engine.active ? '正在协作' : engine.agent ? '随时开始一项工作' : '任命已有的工作搭档'}</small></span><ChevronRight size={15}/></button><div className="go-bottom-actions"><button aria-label="Avatar" title="Avatar" onClick={() => void avatar()} disabled={!engine.agent || avatarBusy}><Sparkles size={14}/>Avatar</button><button aria-label="偏好" title="偏好" disabled={!engine.ready} onClick={() => setModal('settings')}><Settings2 size={15}/>偏好</button></div></div>
    </aside>
    <main className="go-main">
      <header className="go-topbar"><div className="go-breadcrumb">工作空间<ChevronRight size={13}/><span>{currentWork && view === 'work' ? currentWork.title : selectedProject?.name || selectedTitle}</span></div><div className="go-topbar-right"><span className="go-local"><i/>保存在本机</span><button className="go-round-button" aria-label="语音协作" disabled={!engine.agent || Boolean(engine.active)} onClick={() => setModal('voice')}><Mic size={17}/></button><button className="go-round-button" aria-label="切换主题" onClick={() => void perform(() => engine.toggleTheme())}>{workspace?.theme === 'dark' ? <Sun size={17}/> : <Moon size={17}/>}</button></div></header>
      {avatarNotice && <div className="go-notice" role="status"><Sparkles size={17}/><span>{avatarNotice}</span><button aria-label="关闭形象提示" onClick={() => setAvatarNotice('')}><X size={15}/></button></div>}
      {engine.error && <div className="go-error" role="alert"><AlertCircle size={17}/><span>{engine.error}</span><button onClick={() => engine.clearError()} aria-label="关闭错误提示"><X size={15}/></button></div>}
      {!engine.ready ? <Empty icon={<Layers size={32}/>} title={engine.error ? '工作区暂时不可用' : '正在打开你的工作区'} action={engine.error ? <Button onClick={() => location.reload()}>重新连接</Button> : undefined}>项目和成果通过 Nimi 的受保护存储保存在本机。</Empty> : currentWork && view === 'work' ? <WorkDetail key={currentWork.id} work={currentWork} suggestedFollowup={workDraft?.workId === currentWork.id ? workDraft.text : undefined} onBack={() => setWorkId(null)} onMaterial={() => setModal('material')} onDoc={id => openDoc(currentWork.id, id)} onRun={async input => { setWorkDraft(null); await engine.run(currentWork.id, input).catch(error => engine.report(error)); }} onStop={() => void perform(() => engine.stop(currentWork.id))} onReuse={() => { setSkill({ id: uuid(), name: `${currentWork.title}的方法`.slice(0, 30), description: '由一项真实工作提炼，可继续修订', instructions: `${workspace?.skills.find(s => s.id === currentWork.skillId)?.instructions || ''}\n\n适用目标：${currentWork.brief}\n\n执行要点：\n${currentWork.steps.map(s => `- ${s.title}`).join('\n')}`, updatedAt: now() }); setModal('skill'); }} onArchive={() => void perform(() => engine.toggleArchive(currentWork.id))}/> : <div className="go-page">
        {view === 'work' && <>
          <div className="go-page-heading go-return-heading"><div><div className="go-eyebrow">{selectedProject ? '项目工作台' : '你的工作台'}</div><h1>{selectedProject?.name || '接着推进工作。'}</h1><p>{selectedProject?.description || '先处理需要你决定的事，再继续最近的工作。'}</p></div>{selectedProject && <Button size="sm" leadingIcon={<Pencil size={14}/>} onClick={() => { setEditingProject(selectedProject); setModal('project'); }}>编辑项目</Button>}</div>
          {!engine.agent && <div className="go-appoint"><div className="go-appoint-icon"><Bot size={25}/></div><div><h3>先选一位你熟悉的搭档</h3><p>{engine.agentError || '任命 Nimi 中已有的 Agent。身份与记忆属于它，项目与工作方法留在这里。'}</p></div><Button onClick={() => setModal('agent')} trailingIcon={<ArrowRight size={15}/>}>选择 Agent</Button></div>}
          {!archive && !search && !attentionOnly && <div className="go-return-grid">
            <section className="go-resume-panel" aria-label="需要你处理"><div className="go-section-head"><h2>需要你处理 <span>{attention.length}</span></h2>{attention.length > 3 && <button onClick={() => setAttentionOnly(true)}>查看全部<ArrowRight size={13}/></button>}</div>{attention.length ? attention.slice(0, 3).map(work => <button className="go-resume-item" key={work.id} onClick={() => setWorkId(work.id)}><Status work={work}/><span><strong>{work.title}</strong><small>{work.question || nextWorkAction(work)}</small></span><ArrowRight size={16}/></button>) : <p className="go-quiet-state">暂时没有待回答或需恢复的工作，可以从下面继续。</p>}</section>
            <section className="go-resume-panel" aria-label="最近成果"><div className="go-section-head"><h2>最近成果</h2><button onClick={() => { setView('deliverables'); setSearch(''); }}>成果库<ArrowRight size={13}/></button></div>{recentDocs.length ? recentDocs.map(({ work, doc }) => <button className="go-resume-item" key={doc.id} onClick={() => openDoc(work.id, doc.id)}><FileText size={20}/><span><strong>{doc.title}</strong><small>{work.title} · v{doc.revisions.length}</small></span><ArrowUpRight size={16}/></button>) : <p className="go-quiet-state">保存后的成果会出现在这里，随时打开、修订和复用。</p>}</section>
          </div>}
          <div className="go-section-head"><div className="go-inline-tabs"><button className={!archive && !attentionOnly ? 'active' : ''} onClick={() => { setArchive(false); setAttentionOnly(false); }}>最近工作</button><button className={attentionOnly ? 'active' : ''} onClick={() => { setArchive(false); setAttentionOnly(true); }}>需要我 · {attention.length}</button><button className={archive ? 'active' : ''} onClick={() => { setArchive(true); setAttentionOnly(false); }}>已归档</button></div><label className="go-search"><Search size={15}/><input aria-label="搜索工作" placeholder="搜索工作…" value={search} onChange={e => setSearch(e.target.value)}/></label></div>
          {visible.length ? <div className="go-work-grid">{visible.map(work => <button key={work.id} className="go-work-card" onClick={() => setWorkId(work.id)}><div className="go-card-top"><span className="go-card-icon"><FileText size={20}/></span><Status work={work}/></div><h3>{work.title}</h3><p>{work.brief}</p><div className="go-card-next">{nextWorkAction(work)}</div><div className="go-card-bottom"><span>{workspace!.projects.find(p => p.id === work.projectId)?.name}</span><span>{work.deliverables.length ? `${work.deliverables.length} 份成果` : date(work.updatedAt)}<ArrowUpRight size={14}/></span></div></button>)}<button className="go-add-card" onClick={() => setModal('work')}><Plus size={23}/><strong>开始下一项工作</strong><span>资料、想法、待推进的事</span></button></div> : <Empty icon={<Folder size={30}/>} title={search ? '没有找到相关工作' : archive ? '这里还没有归档工作' : attentionOnly ? '目前没有需要你处理的工作' : '下一份成果，从这里开始'} action={!archive && !search && !attentionOnly ? <Button tone="primary" onClick={() => setModal('work')}>创建第一项工作<ArrowRight size={16}/></Button> : undefined}>{search ? '换个关键词，或切换到全部项目。' : '写下目标，附上真实资料。你的搭档会执行所需技能，把成果保存下来。'}</Empty>}
          {!archive && <div className="go-method-strip"><span>从成熟的做法开始</span>{workspace!.skills.slice(0, 3).map(s => <button key={s.id} onClick={() => { setSkill(s); setModal('work'); }}><Sparkles size={14}/>{s.name}<ArrowUpRight size={13}/></button>)}</div>}
        </>}
        {view === 'deliverables' && <><PageTitle eyebrow="YOUR WORK, READY TO USE." title="成果会留下，价值会累积。" description="每份成果都保留版本与来源，可以编辑、导出，也可以交给搭档继续改进。"/><div className="go-section-head"><strong>{docs.length} 份成果</strong><label className="go-search"><Search size={15}/><input aria-label="搜索成果" placeholder="搜索成果…" value={search} onChange={e => setSearch(e.target.value)}/></label></div>{docs.length ? <div className="go-document-list">{docs.map(({ work, doc }) => <button key={doc.id} onClick={() => openDoc(work.id, doc.id)}><span className="go-doc-icon"><FileText size={24}/></span><span><strong>{doc.title}</strong><small>{work.title} · {date(doc.revisions.at(-1)!.createdAt)}</small></span><span className="go-revision">v{doc.revisions.length}</span><ArrowUpRight size={17}/></button>)}</div> : <Empty icon={<FileText size={32}/>} title="你交付的东西，都有归处">运行一项工作，Agent 保存的成果会出现在这里。</Empty>}</>}
        {view === 'skills' && <><PageTitle eyebrow="A BETTER WAY, EVERY TIME." title="留下做法，不必从头来过。" description="工作方法属于岗位。你可以修订，也可以交给下一位任职的 Agent。" action={<Button tone="primary" onClick={() => { setSkill(null); setModal('skill'); }}><Plus size={16}/>新建方法</Button>}/><div className="go-work-grid go-skill-grid">{workspace!.skills.map(s => <article className="go-skill-card" key={s.id}><span className="go-card-icon"><Sparkles size={21}/></span><h3>{s.name}</h3><p>{s.description}</p><dl className="go-method-facts"><dt>准备什么</dt><dd>{skillPresentation(s).materials}</dd><dt>会得到什么</dt><dd>{skillPresentation(s).result}</dd></dl><div><Button size="sm" onClick={() => { setSkill(s); setModal('work'); }}>用于新工作<ArrowRight size={14}/></Button><button aria-label={`编辑${s.name}`} onClick={() => { setSkill(s); setModal('skill'); }}><Pencil size={15}/></button></div></article>)}</div><p className="go-footnote">选一个符合当前任务的方法。你可以在编辑中调整所需资料、交付标准与具体执行说明。</p></>}
        {view === 'routines' && <><PageTitle eyebrow="GOOD WORK, ON REPEAT." title="给重要的事，一个固定时间。" description="例行工作在 NimiGo 打开、搭档可用时执行。关闭期间不会补跑；错过的工作可手动开始。" action={<Button tone="primary" onClick={() => { setRoutine(null); setModal('routine'); }}><Plus size={16}/>创建例行</Button>}/>{workspace!.routines.length ? <div className="go-routine-list">{workspace!.routines.map(r => <article key={r.id}><div className="go-routine-time"><strong>{r.time}</strong><span>每天</span></div><div className="go-routine-body"><h3>{r.name}</h3><p>{r.brief}</p><small>{r.enabled ? `下次 ${date(r.nextAt)} · 需要应用保持打开` : '已暂停'}{r.missedAt && ' · 有一次错过，未补跑'}</small>{r.lastWorkId && <button onClick={() => { setView('work'); setWorkId(r.lastWorkId!); }}>查看最近一次结果<ArrowUpRight size={13}/></button>}</div><div className="go-routine-actions"><Button size="sm" onClick={() => void perform(() => engine.runRoutine(r.id))}>现在运行</Button><Button size="sm" tone="ghost" onClick={() => void perform(() => engine.saveRoutine({ ...r, enabled: !r.enabled, nextAt: nextRoutineTime(r.time) }))}>{r.enabled ? '暂停' : '开启'}</Button><button aria-label={`编辑${r.name}`} onClick={() => { setRoutine(r); setModal('routine'); }}><Pencil size={15}/></button></div></article>)}</div> : <Empty icon={<Clock3 size={32}/>} title="让成熟的工作方法定期运行" action={<Button onClick={() => setModal('routine')}>设置第一项例行</Button>}>例如项目进展简报、资料复盘或每日的创作整理。</Empty>}</>}
        {view === 'sources' && <SourcesPanel projectId={projectId} onProject={setProjectId} onWork={id => { setWorkId(id); setView('work'); }} perform={perform} busy={busy}/>}
      </div>}
    </main>
    <Dialog open={modal !== null} onOpenChange={open => { if (!open) closeModal(); }}><DialogContent className={`go-dialog ${modal === 'voice' ? 'go-voice-dialog' : ''}`} onClose={closeModal}><div className="go-dialog-head"><div><DialogTitle>{({ work: '开始一项值得完成的工作', projects: '选择项目', project: editingProject ? '编辑项目' : '为一组工作建个项目', agent: '任命你的工作搭档', material: '把真实资料放进工作', skill: skill ? '修订工作方法' : '保存一种好做法', routine: routine ? '调整例行工作' : '安排一项例行工作', voice: '与同一位搭档语音协作', settings: '工作空间偏好', 'avatar-switch': `让${avatarSwitch?.name || '当前搭档'}来到桌面？` } as Record<string, string>)[modal || 'work']}</DialogTitle><DialogDescription>{modal === 'avatar-switch' ? '桌面上已有另一位伙伴。确认后会切换，项目和成果仍保留。' : modal === 'projects' ? '按项目查看工作，也可以建立一个新项目。' : modal === 'agent' ? '选择 Nimi 中已有的 Agent。更换搭档不会移走项目或成果。' : modal === 'work' ? '说明你想拿到什么结果。资料可以在创建后继续添加。' : modal === 'voice' ? '语音使用当前 Agent 的真实 Conversation 和已配置的 Realtime 路线。' : '修改会保存在当前 NimiGo 工作空间。'}</DialogDescription></div><button aria-label="关闭对话框" onClick={closeModal}><X size={18}/></button></div>
      {engine.error && <div className="go-notice go-warning" role="alert">{engine.error}</div>}
      {modal === 'work' && workspace && <WorkForm projects={projects} skills={workspace!.skills} projectId={projectId === 'all' ? projects[0]!.id : projectId} skillId={skill?.id || 'brief'} busy={busy} submit={(values) => void perform(async () => { const work = await engine.addWork(values.projectId, values.title, values.brief, values.skillId); setWorkId(work.id); setView('work'); setSkill(null); }, true)}/>}
      {modal === 'projects' && <div className="go-project-picker"><Button onClick={() => { setProjectId('all'); setWorkId(null); setView('work'); setSearch(''); setModal(null); }}>全部项目</Button>{projects.map(project => <Button key={project.id} onClick={() => { setProjectId(project.id); setWorkId(null); setView('work'); setSearch(''); setModal(null); }}>{project.name}</Button>)}<Button tone="primary" onClick={() => { setEditingProject(null); setModal('project'); }}><Plus size={16}/>新建项目</Button></div>}
      {modal === 'project' && <SimpleForm key={editingProject?.id || 'new-project'} busy={busy} fields={[{ name: 'name', label: '项目名称', value: editingProject?.name, placeholder: '例如：新产品发布', required: true }, { name: 'description', label: '项目背景', value: editingProject?.description, placeholder: '目标、受众与共同约束；搭档会在执行时参考这些背景。', multiline: true }]} submit={values => void perform(async () => { if (editingProject) await engine.updateProject(editingProject.id, values.name!, values.description!); else { const p = await engine.addProject(values.name!, values.description!); setProjectId(p.id); } setView('work'); setWorkId(null); }, true)} action={editingProject ? '保存项目' : '创建项目'}/>}
      {modal === 'agent' && <div className="go-agent-picker">{engine.agentError && <p className="go-warning">{engine.agentError}</p>}{engine.agents.length ? engine.agents.map(a => <button key={a.agentBinding} onClick={() => void perform(() => engine.assign(a.agentBinding), true)} disabled={Boolean(engine.active)}><span className="go-agent-avatar">{a.avatarUrl ? <img src={a.avatarUrl} alt=""/> : <Bot size={24}/>}</span><span><strong>{a.displayName}</strong><small>{a.agentBinding === workspace?.agentBinding ? '当前任职' : '使用这位 Agent 的身份、人格与记忆'}</small></span>{a.agentBinding === workspace?.agentBinding ? <Check size={20}/> : <ArrowRight size={17}/>}</button>) : <Empty icon={<Bot size={28}/>} title="还没有可用的 Agent">先到 Nimi 的 Agent Center 建立或启用一位 LocalAgent，再回来刷新。</Empty>}<Button onClick={() => void engine.refreshAgents()} leadingIcon={<RefreshCw size={15}/>}>刷新列表</Button>{engine.active && <p className="go-footnote">请先结束当前工作，再更换任职搭档。</p>}</div>}
      {modal === 'material' && currentWork && <MaterialForm busy={busy} onSave={(title, content) => void perform(() => engine.addMaterial(currentWork.id, title, content), true)}/>}
      {modal === 'skill' && <SimpleForm key={skill?.id || 'new'} busy={busy} fields={[{ name: 'name', label: '方法名称', value: skill?.name, required: true }, { name: 'description', label: '什么时候适用', value: skill?.description }, { name: 'materials', label: '所需资料', value: skill ? skillPresentation(skill).materials : '', required: true }, { name: 'result', label: '交付结果', value: skill ? skillPresentation(skill).result : '', required: true }, { name: 'instructions', label: '执行说明（高级）', value: skill?.instructions, multiline: true, required: true }]} action="保存方法" submit={values => void perform(() => engine.saveSkill({ id: skill?.id || uuid(), name: values.name!, description: values.description!, materials: values.materials!, result: values.result!, instructions: values.instructions!, updatedAt: now() }), true)}/>}
      {modal === 'routine' && workspace && <RoutineForm routine={routine} projects={projects} skills={workspace!.skills} busy={busy} onSave={r => void perform(() => engine.saveRoutine(r), true)}/>}
      {modal === 'settings' && workspace && <div className="go-settings"><label><span><strong>交付后通知 Nimi Home</strong><small>发布工作标题、成果数量与打开入口。</small></span><input type="checkbox" checked={workspace!.notifyHome} onChange={e => void perform(() => engine.setNotifyHome(e.target.checked))}/></label><p>项目、方法和成果通过 Nimi 的应用私有存储保存在本机。Agent 的 Conversation 与长期记忆由 Nimi 管理。关窗后已受理的分析继续；退出 NimiGo 会停止执行。例行工作只在窗口打开时触发。</p><Button onClick={() => void engine.refreshAgents()}>刷新 Agent 与访问状态</Button></div>}
      {modal === 'avatar-switch' && avatarSwitch && <div className="go-work-result-actions"><Button tone="primary" loading={avatarBusy} onClick={() => void confirmAvatarSwitch()}>切换到{avatarSwitch.name}</Button><Button disabled={avatarBusy} onClick={closeModal}>保留当前伙伴</Button></div>}
      {modal === 'voice' && engine.agent && <VoiceRoom/>}
    </DialogContent></Dialog>
    {selectedDoc && <DocumentEditor work={engine.getWork(selectedDoc.workId)} doc={engine.getWork(selectedDoc.workId).deliverables.find(d => d.id === selectedDoc.id)!} onClose={() => setSelectedDoc(null)} onReuse={() => { const doc = engine.getWork(selectedDoc.workId).deliverables.find(item => item.id === selectedDoc.id)!; setWorkDraft({ workId: selectedDoc.workId, text: `请先读取「${doc.title}」最新保存的 v${doc.revisions.length}，保留我已确认的修订，再完善这份成果并保存新版本。` }); setWorkId(selectedDoc.workId); setView('work'); setSelectedDoc(null); }}/>}
  </div>;
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="go-page-heading"><div><div className="go-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function SimpleForm({ fields, submit, action, busy }: { fields: { name: string; label: string; value?: string; placeholder?: string; required?: boolean; multiline?: boolean }[]; submit: (values: Record<string, string>) => void; action: string; busy: boolean }) {
  return <form className="go-form" onSubmit={event => { event.preventDefault(); submit(Object.fromEntries(new FormData(event.currentTarget)) as Record<string, string>); }}>{fields.map(field => <Field key={field.name} label={field.label}>{field.multiline ? <TextareaField aria-label={field.label} name={field.name} defaultValue={field.value} placeholder={field.placeholder} required={field.required} rows={6} maxLength={7000}/> : <TextField aria-label={field.label} name={field.name} defaultValue={field.value} placeholder={field.placeholder} required={field.required} maxLength={120}/>}</Field>)}<Button type="submit" tone="primary" loading={busy}>{action}<ArrowRight size={16}/></Button></form>;
}
function WorkForm({ projects, skills, projectId, skillId, submit, busy, work }: { work?: Work; projects: NonNullable<typeof engine.workspace>['projects']; skills: Skill[]; projectId: string; skillId: string; submit: (values: { projectId: string; title: string; brief: string; skillId: string }) => void; busy: boolean }) {
  return <form className="go-form" onSubmit={event => { event.preventDefault(); submit(Object.fromEntries(new FormData(event.currentTarget)) as Parameters<typeof submit>[0]); }}><Field label="工作名称"><TextField name="title" aria-label="工作名称" placeholder="例如：为新产品准备一份发布简报" defaultValue={work?.title} required autoFocus maxLength={120}/></Field><Field label="你想得到什么结果？"><TextareaField name="brief" aria-label="交付目标" placeholder="写下目标、受众、需要包含的内容，以及你在意的约束…" defaultValue={work?.brief} required rows={5} maxLength={4000}/></Field><div className="go-form-columns"><Field label="所属项目"><select name="projectId" aria-label="所属项目" defaultValue={projectId}>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="使用方法"><select name="skillId" aria-label="使用方法" defaultValue={skillId}>{skills.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field></div><Button type="submit" tone="primary" loading={busy}>{work ? '保存工作信息' : '建立工作'}<ArrowRight size={16}/></Button><p className="go-footnote">{work ? '修改目标或方法后回到待开始，已有成果和执行记录保留。' : '建立后可添加资料、修改目标，再交给搭档开始。'}</p></form>;
}
function MaterialForm({ onSave, busy }: { onSave: (title: string, content: string) => void; busy: boolean }) {
  const [title, setTitle] = useState(''); const [content, setContent] = useState('');
  return <form className="go-form" onSubmit={e => { e.preventDefault(); onSave(title, content); }}><label className="go-file-drop"><Upload size={21}/><strong>导入文本或 Markdown</strong><span>每份最多 16 KiB，或直接粘贴下方</span><input type="file" accept=".txt,.md,.csv,.json" onChange={e => { const file = e.target.files?.[0]; if (!file) return; if (file.size > 16384) { engine.report(new Error('这份资料超过 16 KiB，请选择相关片段后粘贴')); return; } void file.text().then(value => { setTitle(file.name); setContent(value); }); }}/></label><Field label="资料名称"><TextField aria-label="资料名称" value={title} onChange={e => setTitle(e.target.value)} required maxLength={80}/></Field><Field label="原始内容"><TextareaField aria-label="资料内容" value={content} onChange={e => setContent(e.target.value)} rows={8} required/></Field><Button type="submit" tone="primary" loading={busy}>加入这项工作</Button></form>;
}
function RoutineForm({ routine, projects, skills, busy, onSave }: { routine: Routine | null; projects: NonNullable<typeof engine.workspace>['projects']; skills: Skill[]; busy: boolean; onSave: (routine: Routine) => void }) {
  return <form className="go-form" onSubmit={e => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)) as Record<string, string>; onSave({ id: routine?.id || uuid(), name: values.name!, brief: values.brief!, time: values.time!, projectId: values.projectId!, skillId: values.skillId!, enabled: routine?.enabled ?? true, nextAt: nextRoutineTime(values.time!), ...(routine?.lastWorkId ? { lastWorkId: routine.lastWorkId } : {}) }); }}><Field label="例行名称"><TextField aria-label="例行名称" name="name" required defaultValue={routine?.name} placeholder="每天的项目进展简报"/></Field><Field label="每次要完成什么"><TextareaField aria-label="例行目标" name="brief" required rows={4} defaultValue={routine?.brief} placeholder="查看新的生态动态，整理进展、风险和需要我处理的事。"/></Field><div className="go-form-columns"><Field label="每天执行时间"><TextField aria-label="执行时间" name="time" type="time" required defaultValue={routine?.time || '09:00'}/></Field><Field label="工作方法"><select name="skillId" aria-label="例行方法" defaultValue={routine?.skillId || 'weekly'}>{skills.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field></div><Field label="所属项目"><select name="projectId" aria-label="例行项目" defaultValue={routine?.projectId || projects[0]?.id}>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><p className="go-notice"><Clock3 size={17}/>NimiGo 窗口与 Nimi 需要保持运行。错过的例行不会自动补跑；你可随时暂停或手动运行。</p><Button tone="primary" type="submit" loading={busy}>保存例行</Button></form>;
}

function WorkDetail({ work, suggestedFollowup, onBack, onMaterial, onDoc, onRun, onStop, onReuse, onArchive }: { work: Work; suggestedFollowup?: string; onBack: () => void; onMaterial: () => void; onDoc: (id: string) => void; onRun: (input?: string) => Promise<void>; onStop: () => void; onReuse: () => void; onArchive: () => void }) {
  const [followup, setFollowup] = useState(''); const [answer, setAnswer] = useState(''); const [editing, setEditing] = useState(false); const [materialId, setMaterialId] = useState<string | null>(null); const [savingWork, setSavingWork] = useState(false);
  const pending = engine.pendingFor(work.id);
  const [readIndex, setReadIndex] = useState('0');
  const [readInput, setReadInput] = useState('{}');
  const [importing, setImporting] = useState(false);
  const messages = engine.messages.get(work.id) || [];
  const material = work.materials.find(item => item.id === materialId);
  useEffect(() => { void engine.refreshIntegrations().catch(error => engine.report(error)); }, []);
  const composer = useRef<HTMLFormElement>(null);
  useEffect(() => { if (suggestedFollowup) { setFollowup(suggestedFollowup); composer.current?.scrollIntoView({ block: 'nearest' }); } }, [suggestedFollowup]);
  const run = (event: FormEvent) => { event.preventDefault(); if (followup.trim()) { const sent = followup; void onRun(sent).then(() => { if (!['failed', 'uncertain'].includes(engine.getWork(work.id).status)) setFollowup(value => value === sent ? '' : value); }); } };
  return <div className="go-work-detail">
    <section className="go-work-body"><button className="go-back" onClick={onBack}><ChevronLeft size={15}/>返回工作台</button><div className="go-work-title"><div><div className="go-eyebrow">{engine.workspace?.projects.find(p => p.id === work.projectId)?.name} / {engine.workspace?.skills.find(s => s.id === work.skillId)?.name}</div><h1>{work.title}</h1></div><Status work={work}/></div>
      <div className="go-brief"><div><span>{editing ? '工作信息' : '交付目标'}</span><button aria-label={editing ? '取消编辑工作' : '编辑工作信息'} disabled={!workCanEdit(work) || savingWork} onClick={() => setEditing(!editing)}>{editing ? <X size={14}/> : <Pencil size={14}/>}</button></div>{editing ? <WorkForm work={work} projects={engine.workspace!.projects.filter(p => !p.archived)} skills={engine.workspace!.skills} projectId={work.projectId} skillId={work.skillId} busy={savingWork} submit={values => { setSavingWork(true); void engine.updateWorkDetails(work.id, values).then(() => setEditing(false)).catch(error => engine.report(error)).finally(() => setSavingWork(false)); }}/> : <p>{work.brief}</p>}</div>
      <div className="go-execution-head"><h2><span className="go-agent-mini"><Bot size={15}/></span>协作记录</h2><span>{work.attempts.length ? `${work.attempts.length} 次委托` : '尚未开始'}</span></div>
      {work.error && <div className="go-notice go-warning"><AlertCircle size={18}/><span>{work.error}</span></div>}
      {work.status === 'draft' && work.queuedInput && <div className="go-notice"><Clock3 size={17}/><span>离开前这项委托还在排队，没有开始执行。资料与要求已保留，准备好后可手动开始。{work.queuedInput.followup && <><br/>本次委托：{work.queuedInput.followup}</>}</span></div>}
      {!work.attempts.length && workCanEdit(work) && <div className="go-ready-card"><Sparkles size={24}/><h3>资料准备好，就可以开始了。</h3><p>搭档会查阅资料、执行技能并保存成果。需要补充信息时，会在这里问你。</p><p className="go-run-boundary">关窗后，已开始的分析继续；“退出并停止 NimiGo”会结束执行。例行工作需保持窗口打开。</p><Button tone="primary" disabled={!engine.agent} onClick={() => onRun()} leadingIcon={<Play size={15}/>}>{engine.active ? '加入工作队列' : '交给搭档开始'}</Button>{!engine.agent && <small>先在左下角任命一位 Agent。</small>}</div>}
      <div className="go-messages">{messages.map(message => <article className={`go-message ${message.role}`} key={message.messageId}><div className="go-message-author">{message.role === 'user' ? '你' : message.role === 'app' ? 'NimiGo · 例行工作' : engine.agents.find(a => a.agentBinding === work.attempts.find(t => t.executionId === message.executionId)?.agentBinding)?.displayName || '工作搭档'}<span>{message.role === 'assistant' ? '已保存的回复' : '委托'}</span></div><Markdown content={message.parts.filter(p => p.kind === 'text').map(p => p.text).join('\n')}/></article>)}</div>
      {work.history.length > 0 && <div className="go-work-history">{work.history.slice(-6).map(item => <div key={item.id}><Check size={14}/><span>{item.text}</span><time>{date(item.at)}</time></div>)}</div>}
      {active(work) && <div className="go-working"><i className="go-live-dot"/><div><strong>{work.status === 'queued' ? '等待当前工作结束' : work.status === 'needs-input' ? '搭档正在等你的补充' : '搭档正在推进这项工作'}</strong><small>{work.status === 'queued' ? '按加入顺序执行，每次一项。' : '执行结果与保存的成果会直接出现在这里。'}</small></div><Button size="sm" tone="ghost" onClick={onStop}><Square size={13}/>停止</Button></div>}
      {pending?.workId === work.id && !pending.change && <form className="go-question" onSubmit={e => { e.preventDefault(); void engine.answer(work.id, answer).then(() => setAnswer('')).catch(error => engine.report(error)); }}><strong>{pending.question}</strong><TextareaField aria-label="回答搭档" value={answer} onChange={e => setAnswer(e.target.value)} rows={3} required placeholder="补充你的判断或需要的信息…"/><Button tone="primary" type="submit">提交回答<ArrowRight size={14}/></Button></form>}
      {pending?.workId === work.id && pending.change && <div className="go-question"><strong>{pending.question}</strong><small>这会修改 Realm 中的源业务，World Studio 会看到新摘要。若来源已经变化，修改会被拒绝。</small><div className="go-source-diff"><div><span>当前摘要</span><p>{pending.change.world.core.identity.summary}</p></div><div><span>建议摘要</span><p>{pending.change.summary}</p></div></div><div className="go-work-result-actions"><Button tone="primary" onClick={() => void engine.decideWorldChange(work.id, true).catch(error => engine.report(error))}>应用到 World Studio</Button><Button onClick={() => void engine.decideWorldChange(work.id, false).catch(error => engine.report(error))}>不修改来源</Button></div></div>}
      {work.attempts.length > 0 && !active(work) && <><div className="go-work-result-actions">{work.status === 'uncertain' && <Button size="sm" onClick={() => void engine.refreshWorkStatus(work.id).catch(error => engine.report(error))}><RefreshCw size={13}/>核对执行结果</Button>}{work.status === 'uncertain' && work.attempts.at(-1)?.executionId && <Button size="sm" onClick={onStop}><Square size={13}/>停止未决执行</Button>}{work.status === 'review' && <Button size="sm" onClick={() => void engine.saveReplyAsDeliverable(work.id).catch(error => engine.report(error))}><FileText size={14}/>把回复保存为成果</Button>}<Button size="sm" onClick={() => onRun()} disabled={!engine.agent}><RefreshCw size={14}/>{work.status === 'failed' ? '重试这次委托' : '重新执行'}</Button><Button size="sm" onClick={onReuse}><Sparkles size={14}/>提炼为方法</Button></div><form ref={composer} className="go-composer" onSubmit={run}><TextareaField aria-label="继续改进" value={followup} onChange={e => setFollowup(e.target.value)} placeholder="继续改进，例如：把建议整理成下周可执行的清单…" rows={3} maxLength={4000}/><div><small>参考本工作已保存的资料、成果与交流</small><Button type="submit" size="sm" tone="primary" disabled={!followup.trim() || !engine.agent}>继续推进<ArrowRight size={14}/></Button></div></form></>}
    </section>
    <aside className="go-work-inspector"><div className="go-inspector-section"><h2>分析可用的连接</h2><p className="go-footnote">本工作只使用你勾选账户的读取操作；配置及许可在 Nimi 中管理。</p>{engine.integrationTargets.flatMap(target => target.operations.filter(operation => operation.effect === 'read' && target.permittedOperations.includes(operation.name)).map(operation => <label key={`${target.targetRef}:${operation.name}`} className="go-connection-option"><input type="checkbox" disabled={!workCanEdit(work)} checked={work.integrationReads?.some(read => read.targetRef === target.targetRef && read.operation === operation.name) || false} onChange={event => { const reads = (work.integrationReads || []).filter(read => read.targetRef !== target.targetRef || read.operation !== operation.name); if (event.target.checked) reads.push({ targetRef: target.targetRef, operation: operation.name }); void engine.selectIntegrationReads(work.id, reads).catch(error => engine.report(error)); }}/><span>{target.displayName} · {operation.name}<small>{target.accountLabel}</small></span></label>))}{Boolean(work.integrationReads?.length) && <form className="go-form" onSubmit={event => { event.preventDefault(); setImporting(true); void Promise.resolve().then(() => engine.importIntegrationMaterial(work.id, Number(readIndex), JSON.parse(readInput))).catch(error => engine.report(error)).finally(() => setImporting(false)); }}><select aria-label="读取哪个已选操作" value={readIndex} onChange={event => setReadIndex(event.target.value)}>{work.integrationReads!.map((read, index) => <option key={`${read.targetRef}:${read.operation}`} value={index}>{engine.integrationTargets.find(target => target.targetRef === read.targetRef)?.displayName} · {read.operation}</option>)}</select><details><summary>读取参数（高级）</summary><TextareaField aria-label="集成资料读取参数" value={readInput} onChange={event => setReadInput(event.target.value)} rows={5}/><small>{engine.integrationTargets.find(target => target.targetRef === work.integrationReads?.[Number(readIndex)]?.targetRef)?.operations.find(operation => operation.name === work.integrationReads?.[Number(readIndex)]?.operation)?.inputSchemaJson}</small></details><Button type="submit" size="sm" disabled={!workCanEdit(work)} loading={importing}>读取集成资料</Button>{importing && <Button type="button" size="sm" onClick={() => void engine.stop(work.id).catch(error => engine.report(error))}>取消读取</Button>}<small>保存真实读取结果为资料，无需 Agent。</small></form>}{engine.integrationTargets.length === 0 && <p className="go-footnote">尚无可用连接。仍可分析已附资料。</p>}</div><div className="go-inspector-section"><h2>成果<span>{work.deliverables.length}</span></h2>{work.deliverables.length ? work.deliverables.map(doc => <button className="go-inspector-doc" key={doc.id} onClick={() => onDoc(doc.id)}><FileText size={20}/><span><strong>{doc.title}</strong><small>v{doc.revisions.length} · {date(doc.revisions.at(-1)!.createdAt)}</small></span><ArrowUpRight size={14}/></button>) : <p className="go-inspector-empty">交付时，成果会留在这里。<br/>以后还能修改、导出和复用。</p>}</div><div className="go-inspector-section"><h2>工作资料<button onClick={onMaterial} aria-label="添加资料" disabled={!workCanEdit(work)}><Plus size={16}/></button></h2>{work.materials.map(item => <button key={item.id} aria-label={item.title} title={item.title} className="go-material-item" onClick={() => setMaterialId(item.id)}><BookOpen size={16}/><span><strong>{item.title}</strong><small>{item.editedAt ? '用户修订' : item.origin?.title || '你提供的资料'}</small></span></button>)}<button className="go-add-material" onClick={onMaterial} disabled={!workCanEdit(work)}><Plus size={16}/>{work.materials.length ? '添加更多资料' : '添加文本 / 导入资料'}</button></div>{work.steps.length > 0 && <div className="go-inspector-section"><h2>推进清单</h2>{work.steps.map(step => <label className="go-step" key={step.id}><input type="checkbox" checked={step.done} onChange={e => void engine.setStepDone(work.id, step.id, e.target.checked).catch(error => engine.report(error))}/><span>{step.title}</span></label>)}</div>}<div className="go-inspector-meta"><span>建立于 {date(work.createdAt)}</span><span>更新于 {date(work.updatedAt)}</span><button onClick={onArchive} disabled={active(work)}><Archive size={14}/>{work.archived ? '恢复到工作台' : '归档这项工作'}</button></div></aside>
    {material && <MaterialEditor key={material.id} work={work} material={material} onClose={() => setMaterialId(null)}/>}
  </div>;
}
function MaterialEditor({ work, material, onClose }: { work: Work; material: Material; onClose: () => void }) {
  const [editing, setEditing] = useState(false);
  const [title, setTitle] = useState(material.title);
  const [content, setContent] = useState(material.content);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState('');
  const dirty = title !== material.title || content !== material.content;
  const close = () => {
    if (saving) return;
    if (dirty) { setNotice('有尚未保存的资料修改。请保存，或放弃修改后关闭。'); return; }
    onClose();
  };
  const save = async (event: FormEvent) => {
    event.preventDefault(); setSaving(true); setNotice('');
    try { const revised = await engine.updateMaterial(work.id, material.id, title, content); setTitle(revised.title); setContent(revised.content); setEditing(false); }
    catch (error) { setNotice(errorText(error)); }
    finally { setSaving(false); }
  };
  return <Dialog open onOpenChange={open => { if (!open) close(); }}><DialogContent className="go-dialog" onClose={close}>
    <div className="go-dialog-head"><div><DialogTitle>{editing ? '修订工作资料' : material.title}</DialogTitle><DialogDescription>{material.origin ? `${material.origin.title} · 来源更新于 ${date(material.origin.updatedAt)}` : '你提供的资料'}{material.editedAt ? ` · 用户修订于 ${date(material.editedAt)}` : ''}</DialogDescription></div><button onClick={close} aria-label="关闭资料" disabled={saving}><X size={18}/></button></div>
    {notice && <div className="go-notice" role="alert"><span>{notice}</span>{dirty && <button disabled={saving} onClick={onClose}>放弃修改并关闭</button>}</div>}
    {editing ? <form className="go-form" onSubmit={event => void save(event)}>
      <Field label="资料名称"><TextField aria-label="资料名称" value={title} onChange={event => setTitle(event.target.value)} required maxLength={80}/></Field>
      <Field label="资料内容" hint="最多 16 KiB。修订后，搭档会读取新内容；已有成果保留，工作等待重新执行。"><TextareaField aria-label="资料内容" value={content} onChange={event => setContent(event.target.value)} rows={10} required/></Field>
      {material.origin && <p className="go-footnote">修改只保存在这项工作里，保留出处并标为“用户修订”。源应用的内容不会随之改变。</p>}
      <div className="go-work-result-actions"><Button type="submit" tone="primary" loading={saving} disabled={!dirty || !workCanEdit(work)}>保存资料</Button><Button disabled={saving} onClick={() => { setTitle(material.title); setContent(material.content); setEditing(false); setNotice(''); }}>取消修订</Button></div>
    </form> : <><div className="go-material-preview"><Markdown content={material.content}/></div><div className="go-work-result-actions"><Button leadingIcon={<Pencil size={14}/>} disabled={!workCanEdit(work)} onClick={() => setEditing(true)}>修订资料</Button></div>{!workCanEdit(work) && <p className="go-footnote">结束或核对本次执行后，可以修订资料。</p>}</>}
  </DialogContent></Dialog>;
}
function DocumentEditor({ work, doc, onClose, onReuse }: { work: Work; doc: Deliverable; onClose: () => void; onReuse: () => void }) {
  const [version, setVersion] = useState(doc.revisions.at(-1)!.id); const [content, setContent] = useState(''); const [title, setTitle] = useState(doc.title); const [editing, setEditing] = useState(false); const [loading, setLoading] = useState(false); const [dirty, setDirty] = useState(false); const [notice, setNotice] = useState('');
  const revision = doc.revisions.find(r => r.id === version) || doc.revisions.at(-1)!;
  useEffect(() => { let canceled = false; setLoading(true); void engine.store.readText(revision.path).then(value => { if (!canceled) { setContent(value); setDirty(false); } }).catch(error => engine.report(error)).finally(() => { if (!canceled) setLoading(false); }); return () => { canceled = true; }; }, [revision.path]);
  const close = () => { if (dirty) { setNotice('你有尚未保存的修改。请先保存新版本，或点击“放弃修改”。'); return; } onClose(); };
  const versionNumber = doc.revisions.findIndex(value => value.id === revision.id) + 1;
  const copyReference = async () => {
    if (dirty) { setNotice('请先保存新版本，再复制读取引用。'); return; }
    try {
      const reference = deliverableReadReference(work, doc.id, revision.id);
      await navigator.clipboard.writeText(JSON.stringify(reference));
      setNotice(`已复制「${reference.title}」v${reference.version} 的引用，可粘贴到 Day 的 Go 资料入口。`);
    } catch (error) { setNotice(`复制未完成：${errorText(error)}。可展开高级详情手动复制三项 ID。`); }
  };
  return <Dialog open onOpenChange={open => { if (!open) close(); }}><DialogContent className="go-document-dialog"><div className="go-document-toolbar"><div><DialogTitle>{doc.title}</DialogTitle><DialogDescription>{work.title} · {revision.by === 'agent' ? 'Agent 交付' : '你修订'} · {date(revision.createdAt)}</DialogDescription></div><button aria-label="关闭成果" onClick={close}><X size={20}/></button></div><div className="go-document-actions"><select aria-label="成果版本" value={revision.id} disabled={dirty} onChange={e => setVersion(e.target.value)}>{doc.revisions.map((r, i) => <option key={r.id} value={r.id}>v{i + 1} · {date(r.createdAt)} · {r.by === 'agent' ? 'Agent' : '你'}</option>)}</select><Button size="sm" onClick={() => setEditing(!editing)}><Pencil size={14}/>{editing ? '预览' : '编辑'}</Button><Button size="sm" disabled={loading} onClick={() => void engine.client.storage.assets.reveal(revision.path).catch(error => engine.report(error))}><ExternalLink size={14}/>在文件夹中显示</Button><Button size="sm" tone="ghost" onClick={() => { if (dirty) { setNotice('请先保存新版本，再交给搭档改进。'); return; } onReuse(); }}>交给搭档改进<ArrowRight size={14}/></Button></div>{notice && <div className="go-notice">{notice}{dirty && <button onClick={() => { setDirty(false); onClose(); }}>放弃修改</button>}</div>}<div className="go-version-reference"><div><span>在 Day 等获准应用中使用这份成果</span><Button size="sm" disabled={dirty || loading} onClick={() => void copyReference()}><Copy size={14}/>复制版本引用</Button></div><small>引用已保存的 v{versionNumber}，不包含未保存修改。读取时 Go 需保持运行。</small><details><summary>精确读取 ID（高级）</summary><code>{JSON.stringify({ workId: work.id, deliverableId: doc.id, revisionId: revision.id })}</code></details></div><div className="go-document-content">{loading ? <p>正在打开成果…</p> : editing ? <><TextField aria-label="成果标题" value={title} onChange={e => { setTitle(e.target.value); setDirty(true); }}/><TextareaField aria-label="编辑成果正文" value={content} onChange={e => { setContent(e.target.value); setDirty(true); }} rows={20} textareaClassName="go-document-source"/></> : <Markdown content={content}/>}</div><footer className="go-document-footer"><span>{new TextEncoder().encode(content).length.toLocaleString()} 字节 · Markdown · 版本完整保留</span><Button tone="primary" size="sm" disabled={!dirty || loading} onClick={() => { setLoading(true); void engine.saveDeliverable(work.id, title, content, 'user', doc.id, '手动修订').then(result => { setVersion(result.revision); setDirty(false); setNotice('已保存为新版本'); }).catch(error => engine.report(error)).finally(() => setLoading(false)); }}>保存新版本<Check size={14}/></Button></footer></DialogContent></Dialog>;
}
function VoiceRoom() {
  const [host] = useState(() => createBrowserAgentRealtimeHostMediaPort());
  return <AgentRealtimeEntry client={engine.client} initialAgentHandle={engine.agent!.agentHandle} inputAudio={{ codec: 'pcm-s16le', sampleRateHz: 16000, channelCount: 1, frameDurationMs: 20, maximumFrameBytes: 640 }} turnDetection="server-vad" host={host} locale="zh"/>;
}

function SourcesPanel({ projectId, onProject, onWork, perform, busy }: { projectId: string; onProject: (id: string) => void; onWork: (id: string) => void; perform: (action: () => Promise<unknown>) => Promise<void>; busy: boolean }) {
  const projects = engine.workspace!.projects.filter(project => !project.archived);
  const project = projects.find(item => item.id === projectId);
  const [allSourceRef, setAllSourceRef] = useState('');
  const [includeRuntime, setIncludeRuntime] = useState(false);
  const [query, setQuery] = useState('');
  const [targetId, setTargetId] = useState('');
  const sourceRef = project ? project.sourceRef || '' : allSourceRef;
  useEffect(() => { setTargetId(''); setQuery(''); void engine.refreshActivities(sourceRef || null).catch(error => engine.report(error)); }, [projectId, sourceRef]);
  const records = visibleActivities(engine.activities, includeRuntime, query);
  const sources = [...engine.activitySources.values()].filter(source => source.kind === 'app');
  const targets = engine.works.filter(work => !work.archived && workCanEdit(work) && (!project || work.projectId === project.id));
  const target = targets.find(work => work.id === targetId);
  const attach = async (activity: NimiAppActivityRecord) => {
    const work = target || await engine.addWork(project?.id || projects[0]!.id, activity.title.slice(0, 80), `依据带入的来源资料，整理需要跟进的工作与待核对信息，保存一份可执行的建议。\n${activity.title}`, 'brief');
    await engine.addMaterial(work.id, activity.title.slice(0, 80), activity.summary || activity.title, { activityId: activity.activityId, title: activity.source.displayName || activity.source.appId || 'Nimi', updatedAt: activity.updatedAt });
    onWork(work.id);
  };
  return <>
    <PageTitle eyebrow="带着出处开始" title="为当前项目选资料。" description="选择相关来源，把真实动态放进已有工作。来源内容保留出处与更新时间。" action={<Button loading={engine.activityLoading} onClick={() => void perform(() => engine.refreshActivities(sourceRef || null))}><RefreshCw size={15}/>刷新动态</Button>}/>
    <div className="go-source-controls go-form">
      <div className="go-form-columns"><Field label="用于哪个项目"><select aria-label="来源项目" value={projectId} onChange={event => onProject(event.target.value)}><option value="all">全部项目</option>{projects.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label={project ? '本项目关注的来源' : '筛选应用来源'}><select aria-label="关注来源" value={sourceRef} onChange={event => { const value = event.target.value; if (project) void perform(() => engine.setSource(project.id, value)); else setAllSourceRef(value); }}><option value="">全部应用来源</option>{sourceRef && !sources.some(source => source.sourceRef === sourceRef) && <option value={sourceRef}>此前选择的来源</option>}{sources.map((source, index) => <option key={source.sourceRef} value={source.sourceRef}>{source.displayName || source.appId || '应用来源'}{sources.filter(item => item.displayName === source.displayName).length > 1 ? ` · 来源 ${index + 1}` : ''}</option>)}</select></Field></div>
      <div className="go-source-options"><label className="go-search"><Search size={15}/><input aria-label="搜索来源动态" placeholder="在已载入动态中搜索…" value={query} onChange={event => setQuery(event.target.value)}/></label><label><input type="checkbox" checked={includeRuntime} onChange={event => setIncludeRuntime(event.target.checked)}/>显示 Agent 对话动态</label><span>{engine.activities.length} 条已载入{engine.activityNextPage ? ' · 还有更多' : ''}</span></div>
      <Field label="带入哪项工作"><select aria-label="资料目标工作" value={target?.id || ''} onChange={event => setTargetId(event.target.value)}><option value="">带入时新建工作</option>{targets.map(work => <option key={work.id} value={work.id}>{work.title}</option>)}</select></Field>
      {project?.sourceRef && <p className="go-footnote">关注来源已为此项目保存。搭档查询生态动态时也会使用这个范围。</p>}
    </div>
    {records.length ? <div className="go-activity-list">{records.map(activity => <article key={activity.activityId}><span className="go-source-initial">{(activity.source.displayName || activity.source.appId || 'N').slice(0, 1)}</span><div><small>{activity.source.displayName || activity.source.appId || 'Agent'} · {date(activity.updatedAt)}{activity.kind === 'todo' ? ` · ${activity.todoState === 'open' ? '来源待办未完成' : activity.todoState === 'completed' ? '来源已完成' : '来源已取消'}` : ''}</small><h3>{activity.title}</h3><p>{activity.summary || '来源没有提供摘要，可以打开原事项查看。'}</p><div><Button size="sm" disabled={!activity.source.available || !activity.objectRef || busy} onClick={() => void perform(async () => { const result = await engine.client.activity.open({ activityId: activity.activityId }); if (result.outcome !== 'opened') throw new Error(`来源未打开：${result.reason}`); })}>打开来源<ExternalLink size={13}/></Button><Button size="sm" tone="ghost" disabled={busy} onClick={() => void perform(() => attach(activity))}>{target ? '加入所选工作' : '带入新工作'}<ArrowRight size={13}/></Button></div></div></article>)}</div> : <Empty icon={<Link2 size={28}/>} title={engine.activityLoading ? '正在读取来源' : '当前范围没有相关动态'}>{query ? '可换个关键词、切换来源，或加载后续动态。' : '默认收起 Agent 对话通知。选择相关应用来源，或载入更多动态；未显示不代表源应用没有待办。'}</Empty>}
    {engine.activityNextPage && <Button className="go-load-more" loading={engine.activityLoading} onClick={() => void perform(() => engine.refreshActivities(sourceRef || null, true))}>加载更多动态</Button>}
    <p className="go-footnote">动态只是来源摘要。打开或带入资料不会完成原事项；业务状态以源应用为准。</p>
    <details className="go-world-sources"><summary>World Studio 世界资料</summary><div className="go-section-head"><span>从实际世界资料开始评审</span><Button size="sm" onClick={() => void perform(() => engine.refreshWorlds())}>读取世界资料<RefreshCw size={13}/></Button></div>{engine.worlds.slice(0, 12).map(world => <article key={world.id}><BookOpen size={20}/><div><strong>{world.core.identity.name}</strong><p>{world.core.identity.summary}</p><small>源版本 {world.contentRevision} · {date(world.updatedAt)}</small></div><Button size="sm" onClick={() => void perform(async () => { const work = await engine.addWork(project?.id || projects[0]!.id, `改进「${world.core.identity.name}」的表达`.slice(0, 80), `阅读 World Studio 来源 ${world.id}，评审世界摘要。先保存评审成果，来源修改需要我审核后才能应用。`, 'review'); onWork(work.id); })}>评审与改进<ArrowRight size={13}/></Button></article>)}</details>
  </>;
}
